properties.query:
let alertWindow = 15m;
let entropyThreshold = 7.5;
let bytesThreshold = 1000.0;
UAVSatcomLink_CL
| where TimeGenerated > ago(alertWindow)
| where isnotnull(PayloadEntropy) and PayloadEntropy > entropyThreshold and PayloadBytes > bytesThreshold
| extend TriggerReason = strcat("암호키자재유출의심_고엔트로피SATCOM페이로드_entropy_", tostring(PayloadEntropy), "_bytes_", tostring(PayloadBytes))
| extend Severity = "High"
| project TimeGenerated, UAVId, LinkId, SessionId, SrcAddr, DstAddr, Mode, Encoding, PayloadEntropy, PayloadBytes, TriggerReason, Severity
| order by TimeGenerated desc
